package com.bananalab.lite;
import android.content.Context;import java.util.*;import java.util.regex.*;
/** Conversational front end for the real on-device Java compiler. No arbitrary-code claim. */
final class JavaChat{
 static volatile String progress="";static volatile Thread owner;
 static void phase(String text){if(Thread.currentThread()==owner)progress=text;}
 static final class Change{String command="",summary="",error="";boolean handled;}
 static String[] current(String source)throws Exception{Matcher m=Pattern.compile("celebration\\(\\)\\s*\\{\\s*return\\s*\"([^\"]*)\"").matcher(source);if(!m.find())throw new IllegalArgumentException("No pude leer la celebración actual.");return JavaPatchPolicy.sequence(m.group(1));}
 static float currentGap(String source){Matcher m=Pattern.compile("kissGap\\(\\)\\s*\\{\\s*return\\s*([0-9.]+)f?").matcher(source);if(!m.find())throw new IllegalArgumentException("No pude leer la separación actual.");return Float.parseFloat(m.group(1));}
 static String name(String op){return op.equals("baila")?"baile":op.equals("salta")?"salto":op.equals("saluda")?"saludo":op.equals("gira")?"giro":op.equals("aplaude")?"aplauso":"espera";}
 static String describe(String[] ops){List<String> names=new ArrayList<>();for(String op:ops)names.add(name(op));return JavaCompat.join(" → ",names);}
 static List<String> moves(String text){String q=text;String[][] forms={{"salt(?:a|e|ar|ando|o|os)","salta"},{"aplaud(?:e|a|ir|iendo)|aplausos?","aplaude"},{"bail(?:a|e|ar|ando|es)","baila"},{"salud(?:a|e|ar|ando|o|os)","saluda"},{"gir(?:a|e|ar|ando|o|os)|de vueltas","gira"},{"esper(?:a|e|ar|ando|as)","espera"}};for(String[] form:forms)q=q.replaceAll("\\b(?:"+form[0]+")\\b",form[1]);q=q.replaceAll("\\b(?:primero|despues|luego|y|con|un|una|el|la|al|final|por|ultimo|que|se|a|termine|termina|comience|empiece|para|haga|hacer|sea)\\b"," ").replaceAll("\\s+"," ").trim();if(q.isEmpty())return new ArrayList<>();List<String> out=new ArrayList<>();for(String token:q.split(" ")){if(!token.matches("baila|salta|saluda|gira|aplaude|espera"))throw new IllegalArgumentException("No entendí ‘"+token+"’ como movimiento. Puedo usar salto, baile, aplauso, saludo, giro y espera.");out.add(token);}return out;}
 static Change parse(String input,String source)throws Exception{String q=ChatLanguage.normalize(input);Change out=new Change();boolean celebration=q.contains("la celebracion")||q.contains("el festejo"),kiss=q.contains("beso")||q.contains("besarse");if(celebration&&q.matches("(?s)^(?:como|que|cual|por que).*"))return out;
 if(celebration){out.handled=true;if(!q.matches("(?s)^(?:cambia|cambiar|hace|haga|haz|quiero|agrega|anade|quita|saca|pone|en la celebracion|en el festejo|podes|podrias).*")){out.error="Decime cómo querés cambiar la celebración. Por ejemplo: ‘cambia la celebración para que salte y después aplauda’.";return out;}boolean add=q.matches("(?s).*\\b(?:agrega|anade)\\b.*"),remove=q.matches("(?s).*\\b(?:quita|saca)\\b.*");String body=q.replaceFirst("^(?:podes|podrias) ","").replaceFirst("^(?:hace que |haz que |quiero que )","");body=body.replaceAll("\\b(?:cambia|cambiar|hacer|hace|haga|haz|agrega|anade|quita|saca|pone|quiero|en|de|la celebracion|el festejo)\\b"," ").replaceAll("\\s+"," ").trim();List<String> parsed;try{parsed=moves(body);}catch(IllegalArgumentException unknown){out.error=unknown.getMessage()+" No cambié el funcionamiento.";return out;}if(parsed.isEmpty()){out.error="Elegí qué movimientos querés. Ejemplo: ‘cambia la celebración por salto y aplauso’. No apliqué cambios.";return out;}List<String> sequence=new ArrayList<>();if(add||remove)sequence.addAll(Arrays.asList(current(source)));if(remove)sequence.removeAll(parsed);else sequence.addAll(parsed);if(sequence.isEmpty()||sequence.size()>8){out.error="La celebración necesita entre uno y ocho movimientos. Conservé la anterior.";return out;}out.command="celebracion "+JavaCompat.join(",",sequence);out.summary="La celebración quedará así: "+describe(sequence.toArray(new String[0]));return out;}
 if(kiss&&q.matches("(?s).*(?:separa|separen|separados|pegado|pegados|acerca|acerquen|cerca|juntos|contacto).*")){out.handled=true;float old=currentGap(source),value=old;if(q.matches("(?s).*(?:separa|separen|separados|pegado|pegados).*"))value=Math.min(4,old+1);else value=Math.max(0,old-1);if(q.matches("(?s).*(?:contacto exacto|se toquen|contacto del beso).*"))value=0;if(value==old){out.error=value==0?"El beso ya usa contacto sin separación. Si todavía se ve mal, necesito revisar la animación; no cambié nada.":"Ya está en la separación máxima admitida. No cambié nada.";return out;}out.command="separacion del beso "+value;out.summary=value>old?"El beso quedará un poco más separado.":"Las caras quedarán más cerca durante el beso.";return out;}
 return out;}
 static BananaEngine.Result handle(Context c,String message)throws Exception{String q=ChatLanguage.normalize(message);if(q.matches("busca como arreglar ese error|busca ayuda para ese error|busca informacion del ultimo error"))return JavaLive.handle(c,"busca este error java");if(q.equals("mostrame el codigo que cambiaste"))return JavaLive.handle(c,"ver java");if(q.matches("como puedo ajustar la app hablando|quiero mejorar la app|mejora la app|como cambio la app|que podes ajustar hablando|como cambio la celebracion|como cambio el festejo|como ajusto el beso|como cambio el beso|arregla la app|mejora el funcionamiento|arregla el funcionamiento"))return MobileCore.say(c,"Podés pedírmelo acá, sin escribir código:\n• Cambia la celebración para que salte y después aplauda.\n• Agrega un giro al final de la celebración.\n• Separa un poco el beso.\n• Mostrame cómo quedó la celebración.\n• Deshace ese ajuste.\n\nCompilo y pruebo los cambios admitidos antes de activarlos. Por ahora puedo ajustar estos comportamientos de una clase preparada; no cualquier parte de la app.","ajuste");
 if(q.matches("que ajustes hiciste|como quedo la celebracion|que hace la celebracion|como es la celebracion"))return MobileCore.say(c,"La celebración actual es: "+describe(current(JavaLive.source(c)))+".\nÚltimo ajuste por chat: "+JavaLive.prefs(c).getString("chatSummary","todavía ninguno")+".","ajuste");
 if(q.matches("deshace ese ajuste|deshace el ultimo ajuste de la app|volve al funcionamiento anterior")){if(JavaLive.prefs(c).getInt("chatRevision",-1)!=JavaLive.prefs(c).getInt("revision",0))return MobileCore.say(c,"No hay un ajuste reciente del chat que pueda revertir de forma directa. El código pudo cambiar por otra vía; revisá Java local.","ajuste");JavaLive.rollback(c);JavaLive.prefs(c).edit().remove("chatRevision").putString("chatSummary","recuperé el funcionamiento anterior").apply();return MobileCore.say(c,"Recuperé el funcionamiento anterior. Los próximos pedidos usarán esa versión; las escenas ya creadas se conservan.","ajuste");}
 Matcher actor=Pattern.compile("(?:hace que |quiero que |podes hacer que |que )?(.+?) (?:celebre|festeje|celebra|festeja)").matcher(q);if(q.matches("mostrame como quedo la celebracion|proba la celebracion")){SceneDraft d=MobileCore.scene(c);SceneDraft.Actor a=d==null?null:d.get(d.focused);if(a==null&&d!=null&&d.cast.size()==1)a=d.cast.get(0);if(a==null)return MobileCore.say(c,"Elegí primero un personaje de la escena para probar la celebración.","ajuste");return celebrate(c,a.name);}
 if(actor.matches()){SceneDraft d=MobileCore.scene(c);if(d==null)return MobileCore.say(c,"Primero creá un personaje para mostrar su celebración.","ajuste");SceneDraft.Actor a=RuntimeProgram.resolve(d,actor.group(1));if(a==null)return MobileCore.say(c,"¿Qué personaje querés que celebre? Nombralo para conservar a los demás.","ajuste");return celebrate(c,a.name);}
 Change change=parse(message,JavaLive.source(c));if(!change.handled)return null;if(!change.error.isEmpty())return MobileCore.say(c,change.error,"ajuste");String edited=JavaLive.patched(JavaLive.source(c),change.command);if(edited.equals(JavaLive.source(c)))return MobileCore.say(c,"La celebración ya tiene esos movimientos. No necesitó otro cambio.","ajuste");owner=Thread.currentThread();try{phase("Entendí el cambio. Preparando el ajuste…");JavaLive.stage(c,edited,JavaLive.prefs(c).getInt("revision",0));phase("Compilando el cambio en tu dispositivo…");JavaLive.activate(c);JavaLive.prefs(c).edit().putString("chatSummary",change.summary).putInt("chatRevision",JavaLive.prefs(c).getInt("revision",0)).apply();return MobileCore.say(c,"Listo. "+change.summary.replace("quedarán","quedaron").replace("quedará","quedó")+"\nEl cambio pasó las comprobaciones y ya está activo. Se usará en los comportamientos correspondientes. "+(change.command.startsWith("separacion")?"Podés reproducir o pedir una escena de beso para verlo, o decir ‘deshace ese ajuste’.":"Podés decir ‘mostrame cómo quedó la celebración’ o ‘deshace ese ajuste’.")+"","ajuste");}catch(Throwable failure){JavaLive.prefs(c).edit().putString("error",failure.toString()).apply();return MobileCore.say(c,"No pude activar el ajuste. Conservé el funcionamiento anterior. Podés pedir ‘busca este error java’ o volver a describir el cambio.\nDetalle: "+failure.getClass().getSimpleName(),"ajuste");}finally{progress="";owner=null;}}
 static BananaEngine.Result celebrate(Context c,String actor)throws Exception{BananaEngine.Result out=JavaLive.handle(c,actor+" celebra en java");if(out!=null&&out.changed)out.text="Así quedó la celebración. Agregué sus movimientos al final de la escena.";return out;}
}
